//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = "ULDSTF05234.gfm";
scwin.fr_SecuGrpId;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.gBzProcsNo;
scwin.gAcptNo;
scwin.gListProcsStatCd;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.gAcptNo;
scwin.gViewerStat; // 처리시 뷰어=P,  조회시 뷰어=R
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};

scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};

scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};

scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt_1.setValue("총 " + dts_List_1.getRowCount() + "건");
};

scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt_2.setValue("총 " + dts_List_2.getRowCount() + "건");
};

scwin.grd_List_1_OnDblClick = function(row, colid) {
    scwin.openRecvDetail(row, colid);
};

scwin.grd_List_2_OnDblClick = function(row, colid) {
    scwin.openDetail(row);
};

scwin.btn_Search_1_onclick = function() {
    scwin.search();
};

scwin.btn_Search_2_onclick = function() {
    scwin.search();
};

scwin.btn_Close_1_onclick = async function() {
    await $c.win.closePopup();
};

scwin.btn_Close_2_onclick = async function() {
    await $c.win.closePopup();
};

scwin.img_Excel_2_onclick = function() {
    if (dts_List_2.getRowCount() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List_2, "소속부변경목록", "", "8");
    }
};

scwin.img_SDATE_onclick = function() {

    //----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_SDATE);
};

scwin.img_EDATE_onclick = function() {

    //----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_EDATE);
};

scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
};

scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() === "") {
        txb_COM_NM.setValue("");
    }
};

// 일반 함수
scwin.searchCode = function() {
    /*
    00726 - 소속부유형코드
    */
    const arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        submitDoneHandler : scwin.sbm_dts_Cod_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    let strCbd = "",
        i, j;
    for (let i = 0; i < arrCid.length; i++) {

        //----W-Craft WebSquare 변환 확인: getElementById----//
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            alert(arrCid[i].cnm);
        }
        strCbd = "A^전체,";
        for (let j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD);
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD !== '2') {
            alert("[소속부변경]업무는 코스닥회사만 해당합니다. 회사을 다시 선택바랍니다");
        }
    }
};

scwin.search = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        let url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=recvMarketAction&inputMessageId=SECT_TYP_CHG_RECV_OUT";
        //alert("vListMdCd :"+vListMdCd);
        dts_List_1.DataID = encodeURI(url);

        //----W-Craft WebSquare 변환 확인: Reset----//
        dts_List_1.Reset();
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        let pAFCHG_SECT_TP_CD = $c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD);
        if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) === "") {
            pAFCHG_SECT_TP_CD = "A";
        }
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        url += "&AFCHG_SECT_TP_CD=" + pAFCHG_SECT_TP_CD;
        url += "&PROCS_STAT_CD=" + $c.stf.getObjectValue(rdo_PROCS_STAT_CD);
        url += "&DATE_TYP=" + $c.stf.getObjectValue(rdo_DATE_TYP);
        url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
        url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/SectionTypeChange.do",
            ref : "",
            target : "dts_List_2=body.content",
            submitDoneHandler : scwin.sbm_dts_List_2_submitdone,
            isProcessMsg : false
        };

        $c.sbm.executeDynamic(sbmOptions);


    }
};

scwin.openDetail = async function(row) {
    scwin.setContnId(row);
    await $c.frame.CreateDialogFrame("ULDSTF05235", "/lstproc/ULDSTF05235.gfm", "소속부변경관리", 200, 50, 710, 725, "window");
};

// 클릭된 값 변수에 셋팅
scwin.openRecvDetail = function(row, colid) {
    scwin.setContnId(row);
    $c.stf.openDisclViewer(scwin.gAcptNo, scwin.gViewerStat);
    /////////////////////
    scwin.search();
};

scwin.setContnId = function(obj) {
    if (eval(obj) > 0) {
        //그리드에서 선택시
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            scwin.gAcptNo = dts_List_1.getCellData(eval(obj), "ACPT_NO");
            scwin.gMainFormCd = dts_List_1.getCellData(eval(obj), "FORM_CD");
            scwin.gFormVer = dts_List_1.getCellData(eval(obj), "FORM_VER");
            scwin.gIsurCd = dts_List_1.getCellData(eval(obj), "ISUR_CD");
            scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

        } else {
            scwin.gBzProcsNo = dts_List_2.getCellData(eval(obj), "BZ_PROCS_NO");
            scwin.gAcptNo = dts_List_2.getCellData(eval(obj), "ACPT_NO");
            scwin.gListProcsStatCd = dts_List_2.getCellData(eval(obj), "LIST_PROCS_STAT_CD");
        }
        //alert("gBzProcsNo():"+gBzProcsNo);

        //alert("gAcptNo():"+gAcptNo);

        //alert("gListProcsStatCd():"+gListProcsStatCd);

    }
};

scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top_1);
    $c.cm.PanelToGroupBox(panel_Top_2);
    MaxTab_01.setSelectedTabIndex(1);
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetMinusDate2(vCurDate, 90));
    edt_EDATE.setValue(vCurDate);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    $c.elw.fn_searchCode();
    scwin.search();
};
